static uint32_t be32(const unsigned char*b){return((uint32_t)b[0]<<24)|((uint32_t)b[1]<<16)|((uint32_t)b[2]<<8)|b[3];}
int cl_parse_docker_candidate(const unsigned char*b,size_t n,struct cl_docker_candidate*out){static const char magic[]="CLDKSEL";size_t size,at,i,profile;if(!b||!out||n<86||n>8192)return 0;for(i=0;i<7;i++)if(b[i]!=(unsigned char)magic[i])return 0;if((b[7]!='1'&&b[7]!='2')||b[8]>1)return 0;size=((size_t)b[9]<<8)|b[10];if(size<3||size>3072||n<11+size+72)return 0;for(i=0;i<size;i++)if(b[11+i]<32||b[11+i]==127)return 0;at=11+size;out->desktop_bytes=be32(b+at);out->docker_bytes=be32(b+at+36);if(!out->desktop_bytes||out->desktop_bytes>536870912||!out->docker_bytes||out->docker_bytes>67108864)return 0;out->machine=b[8];out->base=b+11;out->base_bytes=size;out->desktop_sha=b+at+4;out->docker_sha=b+at+40;out->context_kind=0;out->profile=0;out->profile_bytes=0;out->config_bytes=out->metadata_bytes=0;out->config_sha=out->metadata_sha=0;at+=72;if(b[7]=='1')return n==at;if(n<at+78||b[at]<1||b[at]>2)return 0;out->context_kind=b[at];profile=((size_t)b[at+1]<<8)|b[at+2];at+=3;if(profile<3||profile>3072||n!=at+profile+72)return 0;for(i=0;i<profile;i++)if(b[at+i]<32||b[at+i]==127)return 0;out->profile=b+at;out->profile_bytes=profile;at+=profile;out->config_bytes=be32(b+at);out->metadata_bytes=be32(b+at+36);out->config_sha=b+at+4;out->metadata_sha=b+at+40;if(!out->metadata_bytes||out->metadata_bytes>65536||out->config_bytes>65536||(out->context_kind==1&&!out->config_bytes)||(out->context_kind==2&&out->config_bytes))return 0;if(out->context_kind==2)for(i=0;i<32;i++)if(out->config_sha[i])return 0;return 1;}

int cl_docker_engine_result(const unsigned char*b,size_t n,unsigned char*out,size_t cap,size_t*used){static const char prefix[]={123,34,73,68,34,58,34,0};static const char result[]={123,34,101,110,103,105,110,101,34,58,34,0};static const char tail[]="\",\"endpoint\":\"npipe:////./pipe/dockerDesktopLinuxEngine\"}";size_t i,at=0,size;if(!b||!out||!used||n<10||n>16384)return 0;if(n&&b[n-1]=='\n'){n--;if(n&&b[n-1]=='\r')n--;}for(i=0;i<7;i++)if(b[i]!=(unsigned char)prefix[i])return 0;if(n<10||b[n-2]!='\"'||b[n-1]!='}')return 0;size=n-9;if(!size||size>128)return 0;for(i=7;i<n-2;i++){unsigned char c=b[i];if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c==':'||c=='.'||c=='_'||c=='-'))return 0;}if(cap<11+size+sizeof(tail)-1)return 0;for(i=0;i<11;i++)out[at++]=(unsigned char)result[i];for(i=0;i<size;i++)out[at++]=b[7+i];for(i=0;i<sizeof(tail)-1;i++)out[at++]=(unsigned char)tail[i];*used=at;return 1;}

static int env_ascii(uint16_t*out,size_t cap,size_t*at,const char*s){size_t i;for(i=0;s[i];i++){if(*at>=cap)return 0;out[(*at)++]=(unsigned char)s[i];}return 1;}
static int env_value(uint16_t*out,size_t cap,size_t*at,const uint16_t*s){size_t i;if(!s)return 0;for(i=0;s[i];i++){if(i>=1024||*at>=cap)return 0;out[(*at)++]=s[i];}if(*at>=cap)return 0;out[(*at)++]=0;return 1;}
int cl_docker_environment(const uint16_t*file,const uint16_t*system_root,uint16_t*out,size_t cap){static const uint16_t empty[]={0};size_t at=0;if(!file||!file[0]||!system_root||!system_root[0]||!out)return 0;
 if(!env_ascii(out,cap,&at,"DOCKER_CLI_HINTS=false")||!env_value(out,cap,&at,empty)||!env_ascii(out,cap,&at,"NoDefaultCurrentDirectoryInExePath=1")||!env_value(out,cap,&at,empty)||!env_ascii(out,cap,&at,"PATH=")||!env_value(out,cap,&at,empty)||!env_ascii(out,cap,&at,"ProgramData=")||!env_value(out,cap,&at,file)||!env_ascii(out,cap,&at,"ProgramFiles=")||!env_value(out,cap,&at,file)||!env_ascii(out,cap,&at,"SystemRoot=")||!env_value(out,cap,&at,system_root)||at>=cap){return 0;}
 out[at]=0;return 1;}

static void selection_text(unsigned char*out,size_t*at,const char*s){size_t i;for(i=0;s[i];i++)out[(*at)++]=(unsigned char)s[i];}
static void selection_sha(unsigned char*out,size_t*at,const unsigned char*s){static const char hex[]="0123456789abcdef";unsigned i;out[(*at)++]='\"';for(i=0;i<32;i++){out[(*at)++]=(unsigned char)hex[s[i]>>4];out[(*at)++]=(unsigned char)hex[s[i]&15];}out[(*at)++]='\"';}
int cl_match_docker_context_selection(const unsigned char*b,size_t n,unsigned kind,const unsigned char*cfg,const unsigned char*meta){unsigned char expected[512];size_t at=0,i;if(!b||!meta||(kind!=1&&kind!=2)||(kind==1&&!cfg))return 0;selection_text(expected,&at,"{\"action\":\"select-context\",\"configSHA256\":");if(kind==1)selection_sha(expected,&at,cfg);else selection_text(expected,&at,"null");selection_text(expected,&at,",\"metadataSHA256\":");selection_sha(expected,&at,meta);selection_text(expected,&at,",\"endpoint\":\"npipe:////./pipe/dockerDesktopLinuxEngine\"}");if(n!=at)return 0;for(i=0;i<n;i++)if(b[i]!=expected[i])return 0;return 1;}
